INSERT INTO admin_operation_log VALUES ('738', '1', 'admin/pages', 'POST', '127.0.0.1', '{\"title\":\"Visi dan Misi PPID\",\"slug\":null,\"fulltext\":\"<p><strong>Visi dan Misi PPID<\\/strong><\\/p>\\r\\n\\r\\n<p><strong>VISI :<\\/strong><\\/p>\\r\\n\\r\\n<p>TERWUJUDNYA PELAYANAN INFORMASI YANG AKUNTABEL, TRANPARAN, EFEKTIF DAN EFISIEN SEHINGGA PELAYANAN INFORMASI PUBLIK MENGHASILKAN LAYANAN INFORMASI PUBLIK YANG BERKUALITAS DAN MENYENANGKAN<\\/p>\\r\\n\\r\\n<p><strong>MISI :<\\/strong><\\/p>\\r\\n\\r\\n<ol>\\r\\n\\t<li>MENINGKATKAN PELAYANAN INFORMASI YANG TERBUKA DAN BERKUALITAS<\\/li>\\r\\n\\t<li>MEMBANGUN DAN MENYEDIAKAN SISTEM PELAYANAN INFORMASI YANG CEPAT, TEPAT, MUDAH DAN SEDERHANA<\\/li>\\r\\n\\t<li>MENINGKATKAN DAN MENGEMBANGKAN KOMPETENSI SDM DI BIDANG PELAYANAN INFORMASI SEHINGGA MENJADI SDM YANG HANDAL<\\/li>\\r\\n<\\/ol>\",\"_token\":\"TvEHxFUliqU1OduEnknPkEka2dRdZP0YsEgntBhJ\"}', '2025-07-01 12:57:52', '2025-07-01 12:57:52');
