INSERT INTO admin_operation_log VALUES ('810', '1', 'admin/news', 'POST', '127.0.0.1', '{\"title\":\"Lagi, Pemprov Babel Raih Predikat Provinsi Informatif\",\"slug\":null,\"tags\":[\"Komisi Informasi,Informatif,Babel\"],\"search_terms\":null,\"introtext\":\"<p>Komisi Informasi (KI) Pusat kembali menobatkan Provinsi Kepulauan Bangka Belitung (Babel) sebagai Provinsi Informatif Tahun 2021 dengan total nilai sebesar 95,56. Prestasi ini merupakan yang kedua kali setelah pada tahun 2020, Babel juga meraih predikat Informatif untuk pertama kalinya<\\/p>\",\"fulltext\":\"<p>PANGKALPINANG &ndash; Komisi Informasi (KI) Pusat kembali menobatkan Provinsi Kepulauan Bangka Belitung (Babel) sebagai Provinsi Informatif Tahun 2021 dengan total nilai sebesar 95,56. Prestasi ini merupakan yang kedua kali setelah pada tahun 2020, Babel juga meraih predikat Informatif untuk pertama kalinya. Capaian ini diumumkan secara langsung pada Acara Anugerah Keterbukaan Informasi Publik yang dilaksanakan secara virtual dan dihadiri oleh Wakil Presiden RI, Ma&rsquo;ruf Amin, Selasa (25\\/10\\/2021).<\\/p>\\r\\n\\r\\n<p><br \\/>\\r\\nSaat ini, Provinsi Bangka Belitung menempati urutan keenam dari 34 provinsi setelah Provinsi Jawa Tengah, Provinsi Aceh, Provinsi Nusa Tenggara Barat, Provinsi DKI Jakarta dan Provinsi Riau. Penilaian merupakan hasil pelaksanaan monitoring dan evaluasi Keterbukaan Informasi Publik (KIP) sejak bulan Juli-September 2021 terhadap 43 indikator yang telah ditetapkan.<\\/p>\\r\\n\\r\\n<p>Wakil Presiden Ma&rsquo;ruf Amin pada momen ini mengucapkan selamat kepada Badan Publik (BP) yang telah memperoleh kualifikasi sebagai BP yang informatif.<\\/p>\\r\\n\\r\\n<p>&ldquo;Saya menyambut baik dan mengapresiasi KI Pusat dalam mengawasi dan mengevaluasi capaian KIP di Indonesia serta mengawal penguatan akuntabilitas BP. Penganugrahan ini merupakan kesempatan bagi BP untuk terus mengakselerasi upaya-upaya terbaik mengenai keterbukaan informasi melalui inovasi yang tiada henti,&rdquo; jelasnya saat mengawali sambutan.<\\/p>\\r\\n\\r\\n<p>Pengelolaan KIP dikatakan orang nomor dua di Indonesia ini, dilakukan dalam rangka mendorong partisipasi masyarakat guna terwujudnya tata kelola pemerintah yang baik dan transparan. Sedangkan hasil penilaian diharapkan jadi bahan introspeksi BP untuk terus menjaga dan meningkatkan kinerja pelayanan publik dan produktivitasnya.<\\/p>\\r\\n\\r\\n<p>Dirinya meminta agar semua BP harus menggelorakan KIP. Semua harus terbuka dengan kritik maupun saran dan menyikapinya dengan santun dan beretika berdasarkan norma yang sesuai dengan adab yang berlaku.<\\/p>\\r\\n\\r\\n<p>&ldquo;Karena Negara Indonesia tegas menjamin hak warga negaranya untuk memperoleh informasi sesuai amanat UUD Tahun 1945 serta UU KIP No 14 Tahun 2008. Dan sebagai salah satu negara demokrasi, Indonesia dituntut untuk menjamin keterbukaan informasi sebagai komitmen membangun negara yang transparan dan akuntabel,&rdquo; tegasnya.<\\/p>\\r\\n\\r\\n<p><br \\/>\\r\\nHal yang sama juga dikatakan Sekretaris Daerah Pemprov. Babel, Naziarto usai mengikuti pengumuman penganugerahan KIP hari ini. Ia menyatakan turut bangga mengingat Bangka Belitung mampu mempertahankan predikat Provinsi Informatif selama dua tahun berturut-turut.<\\/p>\\r\\n\\r\\n<p>&ldquo;Pertama-tama kita ucapkan rasa syukur dan bangga, karena dua tahun berturut-turut kita masih bisa mempertahankan capaian sebagai Provinsi Informatif. Untuk tahun-tahun berikutnya kita berharap, ini terus dipertahankan dan kalau bisa kita tingkatkan, paling tidak kita bisa berada di tingkat 3 besar,&ldquo; ungkapnya.<\\/p>\\r\\n\\r\\n<p>Menurutnya, rasa syukur ini dijadikan sebagai momentum untuk terus melakukan perbaikan dalam memberikan pelayanan informasi kepada masyarakat.<\\/p>\\r\\n\\r\\n<p>&ldquo;Diskominfo sebagai PPID Utama serta lokomotif KIP di Provinsi Babel kita harapkan dapat terus meningkatkan koordinasi, sinergitas dan kolaborasi dengan PPID Pembantu maupun stakeholdernya dalam meningkatkan partisipasi publik serta menyediakan informasi yang benar dan akurat agar dapat memenuhi hak-hak masyarakat atas informasi penyelenggaraan pemerintahan daerah,&rdquo; ujarnya lagi.<\\/p>\\r\\n\\r\\n<p>Sementara Kepala Dinas Komunikasi dan Informatika Babel, Sudarman mengatakan peningkatan penilaian pada tahun ini merupakan hasil dari komitmen jajaran pimpinan di lingkungan Pemprov. Babel.<\\/p>\\r\\n\\r\\n<p>&ldquo;Kita patut bersyukur dengan pencapaian pada tahun ini. Jika tahun sebelumnya kita berada pada urutan ke 7, tahun 2021 ini kita naik satu peringkat menjadi urutan ke-6 dari 34 provinsi dan dari 337 BP yang dinilai oleh KI Pusat. Semua itu adalah hasil kerja keras kita semua serta dukungan dan komitmen pimpinan kita mulai dari Pak Gubernur, Wagub, Sekda beserta jajarannya. Dan InsyaAllah, akan meningkat lagi di tahun-tahun mendatang,&ldquo; ujarnya.<\\/p>\\r\\n\\r\\n<p>Dikatakannya lagi, pencapaian ini jangan sampai membuat kita berpuas diri, namun perlu terus dilakukan upaya-upaya dan inovasi di berbagai aspek mengingat ada beberapa catatan yang memang perlu ditingkatkan.<\\/p>\\r\\n\\r\\n<p>&ldquo;Seperti halnya pada aspek kolaborasi dengan pihak lain, perlu kita perbaiki dan ini menjadi PR kita. Kedepan, kita akan berkolaborasi dengan Yayasan Pendidikan Anak Cacat (YPAC) karena pelayanan informasi ini merupakan hak semua orang dan ramah terhadap publik dengan kategori yang berkebutuhan khusus. Tidak hanya itu, sebagai PPID Utama kami juga sudah menyusun program pelayanan dan keterbukaan informasi publik berbasis gender yakni kaum perempuan,&ldquo; jelasnya.<\\/p>\\r\\n\\r\\n<p>&ldquo;Intinya, capaian peringkat bukan yang utama, namun bagaimana pelayanan KIP ini bisa memenuhi hak-hak masyarakat sekaligus meningkatkan partisipasi mereka dalam pembangunan daerah dan bangsa,&ldquo; pungkasnya.<\\/p>\",\"publish_date\":\"2021-10-25\",\"publish_status\":\"1\",\"publish_by\":\"admin\",\"_token\":\"QGyUBmiRFdx5usUdvefMSnowQD0DPgwyjrjRRuhV\"}', '2025-07-03 10:25:23', '2025-07-03 10:25:23');
INSERT INTO admin_operation_log VALUES ('811', '1', 'admin/news', 'GET', '127.0.0.1', '[]', '2025-07-03 10:25:23', '2025-07-03 10:25:23');
