INSERT INTO admin_operation_log VALUES ('816', '1', 'admin/news', 'POST', '127.0.0.1', '{\"title\":\"Raih Provinsi Informatif, Dalam Setahun Pemprov. Babel Naik 4 Tingkatan\",\"slug\":null,\"tags\":[\"Informatif,Babel,pemprov\"],\"search_terms\":null,\"introtext\":\"<p>Pemerintah Provinsi Bangka Belitung (Pemprov. Babel) dinobatkan sebagai Provinsi Informatif. Capaian ini diumumkan langsung pada acara Anugerah Keterbukaan Informasi Publik yang diselenggarakan secara virtual dan dihadiri langsung oleh Wakil Presiden Ma&rsquo;ruf Amin, hari ini Rabu (25\\/11\\/20).<\\/p>\",\"fulltext\":\"<p>Pemerintah Provinsi Bangka Belitung (Pemprov. Babel) dinobatkan sebagai Provinsi Informatif. Capaian ini diumumkan langsung pada acara Anugerah Keterbukaan Informasi Publik yang diselenggarakan secara virtual dan dihadiri langsung oleh Wakil Presiden Ma&rsquo;ruf Amin, hari ini Rabu (25\\/11\\/20).<\\/p>\\r\\n\\r\\n<p>Wakil Gubernur Kepulauan Bangka Belitung (Babel), Abdul Fatah mengatakan, bahwa Pemprov. Babel melakukan lompatan besar dari kategori tidak informatif di tahun 2019 menjadi provinsi informatif di tahun 2020. Wakil Gubernur Abdul Fatah pun mengucapkan selamat atas pencapaian Pemprov. Babel masuk dalam kategori Provinsi Informatif.<\\/p>\\r\\n\\r\\n<p>&ldquo;Ini luar biasa, kita tentunya bangga atas pencapaian Pemerintah Provinsi Bangka Belitung pada hari ini. Ini merupakan lompatan besar setelah tahun sebelumnya kita berada di kategori provinsi yang tidak informatif,&rdquo; ujarnya.<\\/p>\\r\\n\\r\\n<p><br \\/>\\r\\nDari 34 provinsi di Indonesia, Bangka Belitung memperoleh nilai 94,53. Berada di urutan ke tujuh bersama 10 provinsi informatif di Indonesia.<\\/p>\\r\\n\\r\\n<p>Menurutnya, capaian ini tidak lepas dari komitmen dan upaya kita bersama dalam menyediakan dan memberikan pelayanan informasi kepada masyarakat.<\\/p>\\r\\n\\r\\n<p>&ldquo;Predikat ini merupakan hasil monitoring dan evaluasi yang dilaksanakan oleh Komisi Informasi Pusat tahun 2020. Capaian ini harus bisa kita pertahankan, bila mana mungkin harus kita tingkatkan. Ketersediaan dan kemudahan masyarakat memperoleh informasi akan meningkatkan partisipasi masyarakat dalam membangun Bangka Belitung,&rdquo; ujarnya.<\\/p>\\r\\n\\r\\n<p>Menurut Ketua Komisi Informasi Pusat, Gede Nayarana mengatakan bahwa, &ldquo;Dari 348 Badan Publik yang dimonitoring dan dievaluasi sepanjang tahun 2020, mayoritas 254 badan publik (72,99%) masih sangat rendah kepatuhannya dalam melakukan keterbukaan informasi publik. Terdapat 61 badan publik yang masuk kategori cukup informatif, 47 badan publik masuk kategori kurang informatif, dan 146 badan publik masuk dalam kategori yang tidak informatif,&rdquo; ujarnya.<\\/p>\\r\\n\\r\\n<p>Meski banyak badan publik yang tidak informatif namun, tidak sedikit badan publik yang telah berupaya meningkatkan pelayanan keterbukaan informasi publiknya.<\\/p>\\r\\n\\r\\n<p>Predikat perolehan nilai yang telah diumumkan sebagai berikut, nilai tertinggi diperoleh Provinsi Jawa Tengah, dengan nilai 99,15; disusul oleh posisi ke dua Pemprov. DKI 99,07; ketiga Pemprov. Jawa Barat dengan nilai 98,15; keempat Nusa Tenggara Barat dengan nilai 97,29; kelima Aceh dengan nilai 96,73; keenam Pemprov. Banten dengan nilai 96,01. Sedangkan 3 provinsi di bawah Babel yakni Pemprov. Kalimantan Timur dengan nilai 94,40; Pemprov D.I. Yogyakarta dengan nilai 93,83; dan Pemprov Bali dengan nilai 92,20.<\\/p>\\r\\n\\r\\n<p>Sementara itu dalam sambutannya, Wakil Presiden RI, Maruf Amin mengucapkan, selamat kepada provinsi maupun lembaga yang masuk dalam kategori informatif. Menurutnya, pencapaian ini perlu di pertahankan dan bagi lembaga yang masih berada di bawah kategori tersebut untuk segera melakukan akselerasi di bidang keterbukaan informasi publik.<\\/p>\",\"publish_date\":\"2020-11-25\",\"publish_status\":\"1\",\"publish_by\":\"admin\",\"_token\":\"QGyUBmiRFdx5usUdvefMSnowQD0DPgwyjrjRRuhV\"}', '2025-07-03 10:28:39', '2025-07-03 10:28:39');
INSERT INTO admin_operation_log VALUES ('817', '1', 'admin/news', 'GET', '127.0.0.1', '[]', '2025-07-03 10:28:39', '2025-07-03 10:28:39');
