INSERT INTO admin_operation_log VALUES ('859', '1', 'admin/photos', 'POST', '127.0.0.1', '{\"title\":\"Pemprov Babel Wujudkan Komitmen Menuju Babel Informatif\",\"slug\":null,\"introtext\":\"<p>Dalam rangka mewujudkan Babel informatif, Dinas Komunikasi dan Informatika Provinsi Kepulauan Bangka Belitung menggelar kegiatan &ldquo;Asistensi Pengembangan dan Strategi Manajemen Informasi Publik&rdquo; di Ruang Rapat Pasir Padi Kantor Gubernur Kepulauan Bangka Belitung, hari ini, Rabu (4\\/11\\/20).<\\/p>\\r\\n\\r\\n<p>Kegiatan dibuka langsung oleh Wakil Gubernur Kepulauan Bangka Belitung, Abdul Fatah dan dihadiri oleh kepala Dinas Kominfo dari tujuh kabupaten\\/kota, Pejabat Pengelola Informasi dan Dokumentasi (PPID) Utama, PPID pembantu, serta seluruh jabatan fungsional pranata humas di lingkungan Prov. Kepulauan Babel.<\\/p>\\r\\n\\r\\n<p>&nbsp;<\\/p>\",\"publish_date\":\"2020-11-04\",\"publish_status\":\"1\",\"search_terms\":null,\"publish_by\":\"admin\",\"_token\":\"jEgCjAdiiRDUu9AENja50Fqc7BNmz7CJ0JkAA8rf\"}', '2025-07-03 13:58:25', '2025-07-03 13:58:25');
