INSERT INTO admin_operation_log VALUES ('872', '1', 'admin/photos', 'POST', '127.0.0.1', '{\"title\":\"17 Calon Anggota Komisi Informasi Bangka Belitung Ikuti Tes Potensi\",\"slug\":null,\"introtext\":\"<p>Sebanyak 17 peserta mengikuti Tes Potensi Calon Anggota Komisi Informasi (KI) Provinsi Kepulauan Bangka Belitung (Babel) periode 2022-2026 yang berlangsung di Ruang Computer Assisted Test (CAT), Lantai 4 Kantor Gubernur, Senin (21\\/2\\/22).<\\/p>\\r\\n\\r\\n<p>Tes Potensi menggunakan metode CAT Primadona milik BKPSDMD Babel, bertujuan agar tes kompetensi yang merupakan salah satu unsur akan menjadikan seorang anggota Komisi Informasi Babel yang Primadona, yakni memiliki Pribadi yang Mantap dan Dominan Dimana-mana.<\\/p>\",\"publish_date\":\"2022-02-21\",\"publish_status\":\"1\",\"search_terms\":null,\"publish_by\":\"admin\",\"_token\":\"jEgCjAdiiRDUu9AENja50Fqc7BNmz7CJ0JkAA8rf\"}', '2025-07-03 14:06:17', '2025-07-03 14:06:17');
