INSERT INTO page VALUES ('11', 'Struktur Organisasi PPID', '20250701125708-struktur-organisasi-ppid', '<h1>Struktur Organisasi PPID</h1>', 'pages//cb83b86147f900417350aa0fc5ce636d.jpg', '2025-07-01 12:57:08', '2025-07-01 12:57:08');
INSERT INTO page VALUES ('12', 'Tugas dan Fungsi PPID', '20250701125732-tugas-dan-fungsi-ppid', '<p><strong>TUGAS PPID</strong></p>\r\n\r\n<p><strong>(SESUAI DENGAN PERDA NOMOR 6 TAHUN 2019)</strong></p>\r\n\r\n<p><strong>PPID UTAMA mempunyai tugas :</strong></p>\r\n\r\n<ol>\r\n	<li>menyusun dan melaksanakan kebijakan informasi dan dokumentasi;</li>\r\n	<li>menyusun laporan pelaksanaan kebijakan informasi dan dokumentasi;</li>\r\n	<li>mengoordinasikan dan mengkonsolidasikan pengumpulan bahan informasi dan dokumentasi dari PPID Pembantu;</li>\r\n	<li>menyimpan, mendokumentasikan, menyediakan, dan memberi pelayanan informasi dan dokumentasi kepada publik;</li>\r\n	<li>melakukan verifikasi bahan informasi dan dokumentasi publik;</li>\r\n	<li>melakukan uji konsekuensi atas informasi dan dokumentasi yang dikecualikan;</li>\r\n	<li>melakukan pemutakhiran informasi dan dokumentasi;</li>\r\n	<li>menyediakan informasi dan dokumentasi untuk diakses oleh masyarakat;</li>\r\n	<li>melakukan pembinaan, pengawasan, evaluasi, dan monitoring atas pelaksanaan kebijakan informasi dan dokumentasi yang dilakukan oleh PPID Pembantu;</li>\r\n	<li>melaksanakan rapat koordinasi dan rapat kerja secara berkala dan/atau sesuai dengan kebutuhan;</li>\r\n	<li>mengesahkan informasi dan dokumentasi yang layak untuk dipublikasikan;</li>\r\n	<li>menugaskan PPID Pembantu dan/atau Pejabat Fungsional untuk mengumpulkan, mengelola, dan memelihara informasi dan dokumentasi; dan</li>\r\n	<li>membentuk tim fasilitasi penanganan sengketa informasi yang ditetapkan dengan Keputusan Gubernur.</li>\r\n</ol>\r\n\r\n<p><strong>PPID Pelaksana mempunyai tugas :</strong></p>\r\n\r\n<ol>\r\n	<li>membantu PPID Utama melaksanakan tanggungjawab, tugas, dan kewenangannya;</li>\r\n	<li>menyampaikan informasi dan dokumentasi kepada PPID Utama dilakukan paling sedikit 6 (enam) bulan sekali atau sesuai kebutuhan;</li>\r\n	<li>melaksanakan kebijakan teknis informasi dan dokumentasi sesuai dengan tugas pokok dan fungsinya;</li>\r\n	<li>menjamin ketersediaan dan akselerasi pelayanan informasi dan dokumentasi bagi pemohon informasi secara cepat, tepat, berkualitas dengan mengedepankan prinsip pelayanan prima;</li>\r\n	<li>mengumpulkan, mengolah dan mengkompilasi bahan dan data lingkup PD di lingkungan Pemerintahan Daerah menjadi bahan Informasi Publik; dan</li>\r\n	<li>menyampaikan laporan pelaksanaan kebijakan teknis dan pelayanan informasi dan dokumentasi kepada PPID Utama secara berkala dan sesuai dengan kebutuhan.</li>\r\n</ol>\r\n\r\n<p><strong>FUNGSI PPID :</strong></p>\r\n\r\n<ol>\r\n	<li>Menghimpun Informasi Publik yang ada pada Unit Kerja di Lingkungan Pemerintah Provinsi Kepulauan Bangka Belitung</li>\r\n	<li>Penataan dan pendokumentasian Informasi Publik</li>\r\n	<li>Penyelesaian sengketa Informasi</li>\r\n</ol>', null, '2025-07-01 12:57:32', '2025-07-01 12:57:32');
INSERT INTO page VALUES ('13', 'Visi dan Misi PPID', '20250701125753-visi-dan-misi-ppid', '<p><strong>Visi dan Misi PPID</strong></p>\r\n\r\n<p><strong>VISI :</strong></p>\r\n\r\n<p>TERWUJUDNYA PELAYANAN INFORMASI YANG AKUNTABEL, TRANPARAN, EFEKTIF DAN EFISIEN SEHINGGA PELAYANAN INFORMASI PUBLIK MENGHASILKAN LAYANAN INFORMASI PUBLIK YANG BERKUALITAS DAN MENYENANGKAN</p>\r\n\r\n<p><strong>MISI :</strong></p>\r\n\r\n<ol>\r\n	<li>MENINGKATKAN PELAYANAN INFORMASI YANG TERBUKA DAN BERKUALITAS</li>\r\n	<li>MEMBANGUN DAN MENYEDIAKAN SISTEM PELAYANAN INFORMASI YANG CEPAT, TEPAT, MUDAH DAN SEDERHANA</li>\r\n	<li>MENINGKATKAN DAN MENGEMBANGKAN KOMPETENSI SDM DI BIDANG PELAYANAN INFORMASI SEHINGGA MENJADI SDM YANG HANDAL</li>\r\n</ol>', null, '2025-07-01 12:57:53', '2025-07-01 12:57:53');
INSERT INTO page VALUES ('14', 'Daftar Informasi Publik', '20250701125902-daftar-informasi-publik', '<h1>Daftar Informasi Publik</h1>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>SK DIP TAHUN 2024</strong></p>', null, '2025-07-01 12:59:02', '2025-07-01 12:59:02');
