INSERT INTO photo VALUES ('1', 'Pemprov Babel Wujudkan Komitmen Menuju Babel Informatif', '20250703020202-pemprov-babel-wujudkan-komitmen-menuju-babel-informatif', '<p>Dalam rangka mewujudkan Babel informatif, Dinas Komunikasi dan Informatika Provinsi Kepulauan Bangka Belitung menggelar kegiatan &ldquo;Asistensi Pengembangan dan Strategi Manajemen Informasi Publik&rdquo; di Ruang Rapat Pasir Padi Kantor Gubernur Kepulauan Bangka Belitung, hari ini, Rabu (4/11/20).</p>\r\n\r\n<p>Kegiatan dibuka langsung oleh Wakil Gubernur Kepulauan Bangka Belitung, Abdul Fatah dan dihadiri oleh kepala Dinas Kominfo dari tujuh kabupaten/kota, Pejabat Pengelola Informasi dan Dokumentasi (PPID) Utama, PPID pembantu, serta seluruh jabatan fungsional pranata humas di lingkungan Prov. Kepulauan Babel</p>', null, 'photos/3c3c82f5f1dc7b02c3accf814899400e.jpg', '[\"photos\\/4dc294a0b21cfb2c17e00a8c0f355985.jpg\",\"photos\\/d77e4fa9fcb4beda152227c60f556664.jpg\",\"photos\\/b5270b9096f2e3d9660cf2547049ae8e.jpg\"]', '1', '2020-11-04', 'admin', '2025-07-03 14:01:45', '2025-07-03 14:02:02');
INSERT INTO photo VALUES ('2', '17 Calon Anggota Komisi Informasi Bangka Belitung Ikuti Tes Potensi', '20250703020617-17-calon-anggota-komisi-informasi-bangka-belitung-ikuti-tes-potensi', '<p>Sebanyak 17 peserta mengikuti Tes Potensi Calon Anggota Komisi Informasi (KI) Provinsi Kepulauan Bangka Belitung (Babel) periode 2022-2026 yang berlangsung di Ruang Computer Assisted Test (CAT), Lantai 4 Kantor Gubernur, Senin (21/2/22).</p>\r\n\r\n<p>Tes Potensi menggunakan metode CAT Primadona milik BKPSDMD Babel, bertujuan agar tes kompetensi yang merupakan salah satu unsur akan menjadikan seorang anggota Komisi Informasi Babel yang Primadona, yakni memiliki Pribadi yang Mantap dan Dominan Dimana-mana.</p>', null, 'photos/7e1f01dc3dc0ac8a755d8aeebad37877.jpg', '[\"photos\\/c22cf08806c9a8a55dc841e5985c284b.jpg\"]', '1', '2022-02-21', 'admin', '2025-07-03 14:06:17', '2025-07-03 14:06:17');
